const e={langName:"English"},t={appTitle:"DAJING",appSubtitle:"Countdown to the accession",appTagline:"Eighteen months of the throne",day:"Month {day} / {max}",stat:{health:"Body",sanity:"Nerve",money:"Treasury",favor:"Standing"},ap:{label:"Decisions left",upkeep:"Upkeep {n}k/mo · +2k per {every}mo"},goal:{money:"Treasury {money}k taels by accession",favor:"or Standing ≥ {favor}",secured:"Accession assured"},act:{regency:"ACT I · THE CURTAIN",faction:"ACT II · THE FACTIONS",reckoning:"ACT III · THE RECKONING"},action:{endDay:"End the night and retire",confirm:"So be it",hold:"press and hold",restart:"Begin a new reign",start:"Take the throne",share:"Generate share card",continue:"Continue",newGame:"Start over",close:"Close"},story:{premise:"The old emperor died on the autumn hunt and left no edict. You are nineteen, sitting on a chair that is still warm. The Dowager holds the curtain, the Chancellor drafts the decrees, and a general with a hundred thousand men sits at the northern gate. In eighteen months comes your accession — before then, this court has to decide you are its emperor.",switch:"Switch story",pickerTag:"STORY LIBRARY",title:"Choose a world",current:"CURRENT",saved:"Save at month {day} / {max}",hint:"Each story is a separate world. Saves and ending archives never mix.",close:"Close"},badge:{chain:"Consequence",new:"New thread",key:"Pivotal",chainPending:"PENDING",chainFrom:"From month {day}"},roll:{tag:"GAMBLE",win:"IT HELD",lose:"IT FAILED",likely:"likely",even:"even odds",thin:"thin odds",grim:"long odds"},dayCard:{day:"Month {day}",income:"Tax +{n}",spend:"Court -{n}",hint:"tap to continue",off:"don't show this"},interlude:{faction:"In the seventh month, the chair behind the curtain went half an inch empty. They began to practise not looking at you.",reckoning:"The thirteenth month. Everyone knows what you are about to do — except you."},event:{tag:"AUDIENCE",locked:"Locked",apCost:"-{n}",rollWin:"It held",rollLose:"It broke"},log:{title:"Court diary",boot:"You are emperor. Three hundred catties of memorials on the desk, thirty men kneeling outside waiting for you to speak first.",dayStart:"Month {day} begins. Decisions restored to {n}.",upkeepPaid:"Court upkeep: {n}k taels spent.",wage:"Tax silver received: +{n}k taels.",upkeepFail:"The treasury is empty. The guard goes unpaid and riots — Body -25.",arrive:"You move to {loc}.",effectNone:"No change",saved:"Progress saved.",restore:"Another month passes. Nerve +{n}."},ending:{archive:"DAJING ARCHIVE",win:"ACCESSION SECURED",lose:"POWER LOST",rarity:"Ending rarity",trajectory:"Pivotal decisions",noChoice:"Eighteen months, and you did nothing anyone will remember. The historian wrote four characters: no faults in office.",days:"Reigned {n} months",shareHint:"Long-press or right-click to save, then post it",shareFail:"Could not generate the image, try again",sealLine1:"DAJING",sealLine2:"ARCHIVE"},settings:{sound:"Sound",music:"Ambience",on:"On",off:"Off",language:"Language"},contacts:{title:"THE COURT",open:"Court",close:"Back",hint:"What these four think of you decides who stands below the dais on accession day, and who stands behind you.",status:{unknown:"Unmet",met:"Met",ally:"Loyal",betray:"Soured"}},rarity:{1:"Common",2:"Uncommon",3:"Rare",4:"Legendary",5:"Immortal"},share:{label:"DAJING // REIGN RECORD",stats:"FINAL STATE",code:"Record no.",footer:"THE SON OF HEAVEN"}},o={shen:{name:"Shen Yan",role:"Grand Chancellor / three reigns of service",bio:"He drafted edicts for your father for twenty years, and now drafts them for you. Whether your words leave the palace depends on his brush.",stage:{unknown:"You have not summoned him alone yet.",met:"He looks at you before every sentence, weighing an object he hasn't priced.",ally:"He put his own list of names into your hand.",betray:"He has pleaded illness for nine days running."}},dowager:{name:"The Dowager",role:"Empress of the late emperor / holds the curtain",bio:"She knows better than anyone how to sit in that chair without falling off. She said it once: the throne isn't given to you, it's lent.",stage:{unknown:"Through a curtain, you have only heard her voice.",met:"She has started calling you 'the emperor' instead of 'child'.",ally:"She gave you your father's private seal.",betray:"She has moved to the western garden and speaks to no one — including you."}},huo:{name:"Huo Lie",role:"General of the North / a hundred thousand men",bio:"Fourteen years at the northern gate. More scars from frost than from battle. He never kneels, only salutes.",stage:{unknown:"You have only seen the name on victory reports.",met:"He brought three hundred guards to the capital and let four of them in.",ally:"He left half a tiger tally on your desk.",betray:"His dispatches now run four words: I am here. Do not worry."}},wang:{name:"Wang Bao",role:"Chief Eunuch of the Directorate of Ceremonial",bio:"He knows every hidden passage, every burned edict, and the name of every maid who died.",stage:{unknown:"He poured your tea once. You did not remember his face.",met:"He has begun saying things to you that no third person is present to hear.",ally:"He gave you the real ledger of the inner treasury.",betray:"He no longer pours your tea."}}},a={court:{name:"Hall of Supreme Harmony",desc:"Hold court, rule in public, let everyone see whose voice carries."},study:{name:"The Imperial Study",desc:"Sign, dig through old records, draft secret edicts — the truth only shows up alone."},vault:{name:"The Inner Treasury",desc:"Revenues, relief, levies. Money is where loyalty is."},frontier:{name:"The Northern Gate",desc:"Dispatches, generals, war and peace. A blade is always faster than an edict."},chamber:{name:"The Sleeping Chamber",desc:"Sleep, or let one person say the whole thing out loud at night."}},n={chamber_nightmare:{title:"The Dream",desc:"In the dream your father is lying on his bed calling your name. You walk over. He reaches for you and his hand is cold. You try to speak and nothing comes out. You wake with a wet pillow and the sky still black.",choices:{sit_up:{text:"Sit up until dawn. Do nothing",outcome:"You sat there until the sky went grey. At audience the master of rites glanced at you once and said nothing."},call_lamp:{text:"Call someone to light the lamp",outcome:"A young eunuch came in with a lamp and knelt by the bed without lifting his head. You told him to stay. He knelt there until the daylight came in."},write_down:{text:"Write the dream down",outcome:"You wrote one line and found you did not know how to end it. The page stayed on the desk afterwards. Nobody dared move it."}}},chamber_lamp_oil:{title:"Trimming the Wick",desc:"A young eunuch is crouched under the lamp trimming the wick, and he has fallen asleep doing it, the snips still in his hand. There is only this one lamp left burning in the hall.",choices:{let_sleep:{text:"Don't wake him. Trim it yourself",outcome:"You trimmed the wick yourself and the flame came up brighter. He woke at dawn, saw you reading memorials under the lamp, and kowtowed until his forehead was red."},wake_ask:{text:"Wake him. Ask about his family",outcome:"It took him a while to answer: a younger sister in the laundry. You said you would release her next year. He knocked his head on the floor three times, hard."},replace:{text:"Replace him in the morning",outcome:"An older one came the next day. Steady hands, silent with the snips. You never thought about the first one again."}}},chamber_old_robe:{title:"The Old Robe",desc:"At the bottom of a camphor chest there is an old robe. Your father's. There is a patch at the cuff, stitched coarsely — not the wardrobe bureau's work.",choices:{wear:{text:"Put it on",outcome:"It was a little too big and the shoulders sagged. You stood in front of the bronze mirror for a while, then took it off, folded it, and put it back at the very bottom."},burn:{text:"Burn it",outcome:"You burned it in the brazier and it went slowly. The next day the wardrobe asked whether to make a new one. You said no need."},close_lid:{text:"Close the chest",outcome:"You closed the lid and turned the brass lock. You have no idea where the key went. You did not look for it."}}},chamber_mirror:{title:"The Bronze Mirror",desc:"The bronze mirror is polished bright. When you look up, the face in it is your father's at forty — a face you have only seen in paintings.",choices:{stare:{text:"Keep looking. Don't move",outcome:"You looked for a long time. The candle guttered and the face in the mirror guttered with it. You stepped back, and only then did he step back."},cover:{text:"Turn the mirror face down",outcome:"You set it face down on the desk and the sound was muffled. They replaced it afterwards. The new one was never polished again."},ask:{text:"Send someone to ask the empress dowager",outcome:"She sent back one sentence: when your father was forty, he could not sleep either. Nothing more."}}},chamber_taster:{title:"The Taster",desc:"The boy who tasted your soup that day has fallen ill. His face is grey and he no longer knows anyone. The physician calls it a chill. He is fourteen.",choices:{save:{text:"Send the imperial physician. Spare nothing",outcome:"Three days of medicine and he woke. The first thing he asked was whether anyone had drunk the soup. You did not answer."},gift:{text:"Send money to his family. Keep it quiet",outcome:"The money reached his family. He died three days later. The palace register says DIED OF ILLNESS, and paid two taels for the burial."},ignore:{text:"Do nothing",outcome:"You said nothing. The next morning, when the servants carried the soup out, they were very gentle about it, as if afraid of waking someone."}}},chamber_dowager_gift:{title:"A Ring of Keys",desc:"The empress dowager came late, alone, without attendants. She set something down and left: a ring of brass keys, worn shiny. You recognise them. The old storehouse.",choices:{take:{text:"Take them",outcome:"The ring was heavy. You counted: seventeen keys, two missing. You did not ask which two."},refuse:{text:"Push them back",outcome:"You pushed the keys back across the table. She picked them up and said nothing. At the door she paused, then went on."},ask:{text:"Follow her out and ask",outcome:"You caught her in the corridor. She said: your father was missing those two as well. Then she pressed the keys into your hand and left."}}},chamber_wang_knife:{title:"The Man With the Knife",desc:"Wang Bao is kneeling outside the hall with a knife on him. For your protection, he says. The palace has not been calm these past nights. He has been kneeling long enough for the scabbard to sink into the snow.",choices:{trust:{text:"Let him in to stand the night",outcome:"He stood outside the door and did not move once. At dawn you pushed the door open and found him asleep on his knees, his hand still on the knife."},disarm:{text:"Take the knife. Let him stay",outcome:"He unbuckled it and held it out to you in both hands, head down. He stood outside your door all night with empty hands."},banish:{text:"Expel him from the inner court",outcome:"He did not cry out when they dragged him away. The next day everyone in the inner court kept their heads lower than usual when they saw you."},turn_back:{text:"Turn around. Give him your back.",win:"You turn and listen to the breathing behind you. A long time later the knife falls. He kneels and weeps, saying the late emperor asked him to watch over you. You tell him to rise. From then on he walks half a step behind your left shoulder.",lose:"You turn and hear cloth shift. The knife goes in under the shoulder blade and stops against bone. He runs. The blood runs along the brick in a line. The physician says half an inch deeper and there would have been no morning."}}},chamber_last_night:{title:"The Night Before",desc:"The ceremony is tomorrow. The water clock has run to the third watch and you are not remotely sleepy. The edict you must read out is spread on the desk. The first line is not finished.",choices:{sleep:{text:"Sleep",outcome:"You lay down and, to your surprise, slept. You woke to full daylight with the edict still open on the desk. You finished it. You changed not one character.",req:"You cannot — every time you close your eyes you are in your father's room"},walk_hall:{text:"Walk to the throne hall. Sit there alone",outcome:"The hall was empty and your footsteps went all the way up into the beams. You stood in front of the throne for a long time without sitting, then went back and finished the edict."},sit_with_mother:{text:"Go and sit with the empress dowager",outcome:"She did not ask why you had come. She had another quilt brought. You sat and neither of you spoke. Just before dawn she said: go on, then.",req:"There is not that much between you and her"},name_the_taster:{text:"Write the taster's name into the edict",outcome:"You added a line to the general amnesty and wrote one name into it. Nobody knew who he was. When the herald read that line, the hall went quiet for a moment.",req:"The boy did not survive"}}},court_official_audit:{title:"The Grand Evaluation",desc:"The triennial official evaluation arrives. The Ministry of Personnel submits evaluations featuring several names flagged for corruption—who happen to be Shen Yan's favorite protégés. Shen Yan stands at the head of the ranks, waiting to see how you handle the rolls.",choices:{praise:{text:"Go with the flow and grant routine commendations",outcome:"The court remains harmonious, and Shen Yan is well pleased with your compliance. Corruption festers, but you avoid a confrontation."},demote:{text:"Make an example and dismiss two officials on the spot",outcome:"The ministers exchange subtle glances. You claw back two key appointments and squeeze fine money into the treasury, at the cost of Shen Yan lingering his gaze upon you."}}},vault_patrol_routine:{title:"Inspecting the Vault",desc:"You walk the inner treasury alone. Rows of silver ingots gleam coldly beneath dim oil lamps, where an old keeper tallies records with bamboo slips. Here, the empire's lifeblood is reduced to heaps of heavy metal.",choices:{count_coins:{text:"Personally verify the purity and count of a chest of bullion",outcome:"The numbers match. You massage your aching temples; though your mind feels heavy, the extra silver on the ledger brings a measure of security."},chat_keeper:{text:"Dismiss the guards and chat with the old keeper about ordinary town gossip",outcome:"Hearing of common rice and salt beyond the palace walls helps unspool your tight nerves. The crushing weight of power feels slightly lighter for a moment."}}},court_censor_coffin:{title:"The coffin at the steps",desc:"The old censor came into the palace carrying a plain coffin. The memorial is three pages: it accuses the Dowager's brother of eating army pay, conscripting military households, and taking three thousand qing of farmland. The coffin is his own. It sits at the bottom of the steps, and the lacquer has not dried yet.",choices:{flog:{text:"Drag him out. Forty strokes.",outcome:"He stopped making noise at the twenty-seventh. They carried him out alive; the coffin went unused. The next day all thirteen censorate desks submitted resignations together — not asking to leave office, asking you to take the order back. You shelved it without approving anyone."},pardon:{text:"Pardon him, leave the memorial on the desk",outcome:"You say: a remonstrating official has committed no crime. Four words, and half the hall kneels. The memorial is neither issued nor burned. It stays on your desk. At every court session afterwards you can see its corner."},hear:{text:"Let him finish",outcome:"He speaks for half an hour, from army pay to soldiers' widows. Then he knocks his head on the brick until it bleeds. You say: I have heard. Three words do not buy back three thousand qing of land, but from that day the censorate's memorials begin to say what they mean."}}},court_land_survey:{title:"The missing four tenths",desc:"The Ministry of Revenue carries in the land registers: the empire's farmland is four tenths smaller than in the first emperor's reign. Every missing field is marked with the same word — exempt. The exemption was granted to the gentry, and their holdings now exceed a county's.",choices:{survey_all:{text:"Survey every province. Not one field exempt.",outcome:"The order goes out and thirteen provinces move at once. Three months later the acreage is frighteningly good, and the treasury takes in silver nobody budgeted for. The price is that every academy south of the river is writing about you, and writing with style."},survey_small:{text:"Audit the smallholders. Leave the gentry alone.",outcome:"The survey starts in the poorest counties and recovers enough land to pay for a year of river works. The gentry breathe out and send a joint letter of thanks. You accept it, knowing the four tenths are still where they were."},drop_survey:{text:"Drop it. Never raise it again.",outcome:"The Minister of Revenue carries the registers back out, very carefully. You sit in the hall a while longer. Some wars an emperor has to grow into before he can fight them."}}},court_northern_envoy:{title:"The envoy who would not kneel",desc:"The northern envoy stands in the hall and does not kneel. He brings two things: the annual tribute cut in half, and a market. Twelve carts of hides are stopped outside Xuanwu Gate, frozen stiff. He says: our herds for your iron pots and salt. Both sides live.",choices:{feast:{text:"Feast him. Send him back with gifts.",outcome:"He drinks three bowls, and at the gate he kneels once — by their custom, only to heaven and earth. Twenty carts of return gifts go with him, more than his hides. That winter no riders come against the northern gate."},insult:{text:"Have him forced to his knees",outcome:"Two guards press his shoulders down; he never bends. In the end you wave them off. He leaves the twelve carts of hides at the gate, not taking a single one. Three years later his name appears in a battle report from the north."},market:{text:"No tribute talk. Open a market instead.",outcome:"You mark out a ground beyond the pass, set a customs post, and cap iron pots at three catties. The first month's tax is small; the second doubles. Some people look at that silver and see something else: that there is a road besides the sword."}}},court_red_brush:{title:"The red brush",desc:"Wang Bao kneels, holding not a memorial but an old seal with a chipped corner — the Grand Secretariat's vermilion brush seal. He says: Your Majesty reviews three hundred memorials a day, until the third watch, until the brush will not stay in your hand. Let this slave take half. Your Majesty need only nod.",choices:{grant_seal:{text:"Give him the seal",outcome:"From that day memorials go to the Directorate of Ceremonial first, and reach your desk with a slip of paper on each one saying what should be written. Your hand stops aching. You sleep enough. Six months later you realise you have not read a single memorial end to end in three months."},take_seal:{text:"Take the seal back. Lock it in the treasury.",outcome:"The seal goes into the inner vault and the key hangs at your waist. That night you work until the fourth watch and your sight swims at morning court. Wang Bao says nothing from the steps. He only moves the candle a little closer."},split_seal:{text:"Split the brush with the Grand Secretariat. No eunuch touches it.",outcome:"The Chancellor's hand shakes when he takes his half. From then on the Secretariat and the Directorate watch each other. Half the memorials stop coming to your desk, and the ones that come are two factions impeaching each other."}}},court_guard_rotation:{title:"The guard rotation",desc:"Ten days after the letter was intercepted, the commander of the capital guard reports himself ill. The same day the Ministry of War receives three rotation orders for the capital garrison. The dates have been altered — carefully, three days later each. Three days is enough for a column to walk from the west of the city to the palace gate.",choices:{replace_commander:{text:"Take his tally",outcome:"The tally is recovered that night and his residence surrounded. He does not resist. Handing over the seal he says one thing: Your Majesty, this subject never thought of it. You do not know whether he means he never thought of rebelling, or never thought you would suspect him."},double_guard:{text:"Double the watch. Men you trust.",outcome:"Two hundred thousand taels are released and twelve hundred unfamiliar faces appear in the palace. You sleep three full nights. On the fourth, every footstep makes you open your eyes."},wait_and_see:{text:"Say nothing. Watch what he does next.",outcome:"You do nothing. The rotation happens on schedule, the days go on, nothing occurs. Afterwards, every time you pass the gate you count the guards. You stop at the seventh."},rush_gate:{text:"Do not wait for the rotation. Take the guard to the east gate tonight.",win:"The east gate changes its locks, three days ahead of the paperwork. You stand in the archway watching the sky go pale and none of the twenty men beside you speaks. At dawn the commander submits a leave request. He really is ill.",lose:"They moved half a quarter-hour before you. The east gate opens, seven guards die, and your own men carry you back into the inner city. The rotation proceeds the next day and no one mentions the night. Seven coffins leave by the west gate. None of them has a name."}}},court_blood_letter:{title:"The blood letter",desc:"A blood letter is pasted on the examination hall wall. The words are a student's; the blood is the censor's — he died on the seventh day after the flogging. Copies have passed through the six ministries three times, and each copy has a few more sentences than the last.",choices:{hunt_them:{text:"Hunt down everyone who copied it",outcome:"Nineteen are arrested, the youngest sixteen. The wall is scraped clean. What cannot be scraped clean is one sentence: what died under the rod was not a censor, it was the face of the court. It stays in your ear for years."},reverse_it:{text:"Honour him, reverse the sentence, provide for his family",outcome:"The day the order goes out, the students kneel along the whole street. You release two hundred thousand taels: half to the family, half to repair the censorate's old hall. The Chancellor says in open court: this deed is worth ten years of lectures."},let_it_stand:{text:"Don't investigate. Don't acknowledge it.",outcome:"The letter stays on the wall three days and the rain fades it. Nobody dies for it, and nobody is compensated for it. You do nothing, and it passes, the way a great many things pass."}}},court_first_court:{title:"The first court",desc:"The curtain is three paces to your right. The Chancellor lifts a drafted edict: three articles, all ordinary. He is waiting for your seal. The court is waiting for your voice. The Dowager is waiting for you to make a mistake. Water drips from the bronze crane's beak. Once. Again.",choices:{sign:{text:"Sign as drafted",outcome:"The seal comes down and the whole hall exhales at once. Afterwards the Chancellor says: the emperor is wise. You can hear that it is not praise for you. It is praise for a well-behaved child."},amend:{text:"Change one article",outcome:"You change the third: 'implement at once' becomes 'deliberate further'. The hall goes quiet for a long time. The Chancellor looks down at the page and says: as decreed. His brush leaves a single ink blot."},reject_all:{text:"Push the edict back",outcome:"The scroll rolls down the steps and stops at a censor's feet. Nobody picks it up. The curtain moves. You can hear your own heartbeat, loud enough to reach the gate."}}},court_salt_tax:{title:"The salt tax",desc:"The Lianghuai salt commissioner skimmed three hundred thousand taels in three years. The books are clean except one line reading 'a gift'. Follow it and it leads to the Chancellor's own student. The Chancellor kneels below the dais and says nothing at all.",choices:{probe:{text:"Follow it all the way",outcome:"The confiscated silver takes a full day to carry into the treasury. The student is exiled three thousand li. The Chancellor offers his resignation and you refuse it. From that day, the six ministries begin sending memorials around him, straight to your desk."},bury:{text:"Bury it and take his loyalty",outcome:"You move two hundred and fifty thousand taels out of the treasury to plug the hole. Three days later the Chancellor requests a private audience, kneels for half an incense stick, and says on rising: this old man's life belongs to the emperor now."},bleed:{text:"Don't touch the man, take the money",outcome:"The commissioner disgorges three hundred thousand taels and keeps his post. Everyone learns the same lesson: in this court, crimes are purchasable, and the price is posted."}}},court_impeach_huo:{title:"The impeachment of Huo Lie",desc:"The censorate's memorial is longer than a battle report: the northern general holds a hundred thousand men, hasn't entered the capital in three years, raises his own pay, and appoints his own officers. The last line reads: this is not the shape of a subject. Seven signatures sit beneath it.",choices:{try_him:{text:"Send it to the board for judgment",outcome:"The order reaches the northern gate. Huo Lie reads it in front of the courier and drops it into the brazier. He does not rebel. He simply starts filing every dispatch half a month late."},shelve:{text:"Hold it, unsent",outcome:"The memorial goes to the bottom of your desk. You send a hundred and fifty thousand taels north with no explanation. Huo Lie's reply is eight characters: the emperor knows me; I will not fail him."},summon:{text:"Summon him to answer in person",outcome:"He comes with three hundred guards and brings four of them inside. He kneels and does not look up. You do not tell him to rise. You both stay like that until the candle burns out."}}},court_empty_seat:{title:"The empty place",desc:"Halfway through court you notice a gap in the ranks: the Dowager's brother, commander of the imperial guard. Nobody mentions it. Everyone is speaking around that empty patch of floor as if around a hole.",choices:{ask:{text:"Ask, in open court: where is he?",outcome:"Silence. Finally the Dowager speaks from behind the curtain: he is ill. That evening a note arrives in her own hand: the emperor has grown up. The characters are very steady."},cut:{text:"Strip his command while the seat is empty",outcome:"The order goes out the same day and the guard changes hands. Thirty thousand men are re-registered, and the register gains names that were never paid. The Dowager does not sleep. The next morning the curtain is pulled back three inches."},ignore:{text:"Pretend you didn't notice",outcome:"Court ends on schedule. You said nothing, so you got nothing. The empty place stays empty for a full month and nobody fills it."}}},court_grand_audience:{title:"The accession",desc:"The last item of eighteen months. The doors are thrown open, everyone above the sixth rank is present, and the curtain comes down today. The Chancellor holds the edict you wrote yourself and waits at the foot of the steps. You look up at the ceiling. There is a crack in it. It has been there since the day you took the chair.",choices:{declare:{text:"Read it: from today, the emperor rules",outcome:"Your voice bounces off the hall three times. When the edict ends, nobody moves. Then the Chancellor kneels, then the second man, then the tenth, then all of them. Two maids roll up the curtain and carry it away."},purge:{text:"Take the men first, then read it",outcome:"The doors shut behind you and the guard comes in along both colonnades. Wang Bao reads the list: forty-seven names. Sixty thousand taels enter the treasury that day, and the hall is as quiet as an empty house from then on."},abdicate:{text:"Put the seal back on the desk",outcome:"It makes almost no sound when you set it down. The Chancellor freezes, one corner of the edict sliding to the floor. You walk out through the kneeling crowd. Nobody dares look up. Nobody stops you."}}},study_memorial_stack:{title:"Three hundred catties",desc:"Today's stack: three hundred catties. All of it is supposed to be read, all of it signed. The candle is on its third wick and the ones at the bottom haven't been opened. There's dust on the covers.",choices:{work:{text:"Work through all of it",outcome:"By dawn your right hand can't close. Three items in that stack were urgent. One of them would have killed two thousand people if you hadn't sent it back tonight. You sent it back."},skim:{text:"Take the urgent ones, seal the rest",outcome:"You seal them as required. The inner court decides which ones reach you and which don't. You spend the time you saved sleeping two hours."}}},study_forged_edict:{title:"An edict you never spoke",desc:"The chief eunuch brings in an edict, saying it came from your own mouth yesterday and he only copied it out. You said no such thing. It transfers command of three capital battalions. The reasoning is excellent. The seal is genuine.",choices:{burn:{text:"Burn it in front of him",outcome:"You touch the corner to the candle and the fire climbs the characters. He kneels without moving until the ash lands on the back of his hand. The next day, three directors of the Directorate are replaced."},use:{text:"Let it stand and send it out",outcome:"The battalions rotate and nobody questions it. Your grip on the capital tightens by one notch, and the price is that every edict now passes through his hands first. He gets things done for you. He also has you."},trace:{text:"Trace it back",outcome:"You find a clerk in the inner court. The clerk is in a well by nightfall. The trail ends there. What you remember isn't the clerk. It's that the rim of the well had been wiped."}}},study_secret_memorial:{title:"The secret memorial",desc:"A memorial that never passed the cabinet. Eight characters: the northern army unpaid three months, I have sold my horses. Signed Huo Lie, in a rushed hand, with a brown stain on the paper. It could be blood. It could be wine.",choices:{pay:{text:"Send four hundred thousand taels from the treasury",outcome:"The silver leaves the city and you tell no one. Half a month later a herd of horses arrives from the north, listed as captured. The numbers don't add up. You don't ask."},ignore_it:{text:"Lock it away and let him manage",outcome:"You put the memorial in a box. Three months later deserters start appearing at the northern gate, and the numbers in the dispatches get cleaner every time."}}},study_history:{title:"The court diary",desc:"The record of your father's last year, supposed to be sealed by the historians. You open it to the autumn hunt and find three days missing — not unwritten, cut out, with a very straight blade. In the gutter of the binding, half a line survives: ...the emperor took medicine three times.",choices:{read:{text:"Read the rest",outcome:"You sit in the study until dawn. When you finish you know two things: your father did not die of illness, and there are three people left alive who know it. You close the book, put it back, and don't even disturb the dust."},close:{text:"Close it and forget it",outcome:"You shelve the book and put out the lamp. Some truths, once known, make it impossible to be a comfortably ignorant emperor. You decide to stay ignorant a while longer."}}},chamber_bitter_broth:{title:"Broth of Maternal Grace",desc:"Third watch. The Dowager's head eunuch brings a porcelain bowl of bird's nest soup—'boiled under Her Majesty's own eye,' he says. Steam rises, carrying the faint, sharp scent of bitter almonds. He keeps his head bowed, yet his eyes never leave your throat.",choices:{drink:{text:"Drain the bowl while he watches",outcome:"Too sweet. Sickeningly sweet. The eunuch bows out satisfied. An hour later, cramps twist your gut—yet behind the silk screen at dawn, the Dowager praises your filial piety."},reward_eunuch:{text:"Claim no appetite and bestow the bowl upon him",outcome:"Color drains from his face. Hands shaking, he drinks it down. Before an incense stick burns halfway, a dull thud echoes from the side hall. No food ever comes from her palace again."},silver_needle:{text:"Keep it, and test with a silver needle once alone",outcome:"You dismiss the attendants under the pretext of letting it cool. The silver needle emerges with a faint bluish tarnish. You pour the broth into the spittoon, cold sweat soaking your inner robe."}}},study_blood_edict:{title:"The Blood Edict",desc:"Hidden beneath the dragon desk lies a strip of white silk, inked in blood—a secret decree summoning loyalists to retake the capital guard. One seal, and the coup begins tonight. Then you glance at the corridor: your trusted captain of the guard wears a new jade thumb ring from the Dowager.",choices:{send_edict:{text:"Risk everything and dispatch the decree tonight",outcome:"The silk leaves the gate, but never reaches your allies. By dawn, the guard is replaced. The Dowager stands before you holding the bloodied silk, ordering half the windows of the West Pavilion boarded shut."},bribe_guard:{text:"Pay Wang Bao 400,000 taels to silence the captain and use a secret passage",req:"Requires Treasury ≥ 40",outcome:"Wang Bao weighs the silver notes, detains the captain, and slips your decree out through the slop gate. The court trembles, but you survive the night."},burn_edict:{text:"Hold it to the candle flame and burn it yourself",outcome:"Fire curls the blood-red characters into black ash. You stare at the embers until dawn. Your life is spared, yet you know this throne has officially become your cell."}}},chamber_water_pavilion:{title:"The Water Pavilion",desc:"Word of the plot leaked after all. You are moved to an isolated pavilion surrounded by autumn water. Three planks of the wooden bridge are removed, laid down only when meals arrive. Across the water, the Dowager watches beneath a black parasol.",choices:{endure:{text:"Stand by the window and meet her gaze in silence",outcome:"For a quarter hour, neither speaks across the ten yards of water. She turns toward her palanquin, leaving only words carried on the wind: 'Rest well. Leave the realm to me.'"},smash_bridge:{text:"Seize a bronze brazier and shatter the remaining planks",outcome:"Splintered wood sinks into the murky water. Guards across the bank grip their hilts, but the Dowager raises a hand to halt them. For the first time, a flicker of unfamiliarity crosses her eyes."}}},frontier_black_market:{title:"The Frontier Market",desc:"A spy report details an illicit trade outside the Great Wall: General Huo's subordinates melt down obsolete imperial iron plates in exchange for northern horses and furs. At the bottom, Huo's own brush scrawls: 'Starving soldiers cannot fight barbarians.'",choices:{tolerate:{text:"Turn a blind eye and let the gray revenue subsidize the army",outcome:"The imperial treasury gains a stealthy cut, and the northern garrison acquires fresh mounts. Huo offers no effusive thanks, yet victory reports from the frontier grow unusually frequent."},ban_strict:{text:"Issue a stern reprimand and order Huo to stamp out the market within three days",outcome:"The black market is burned to cinders, choking off the garrison's extra grease. Huo sneers in the envoy's face, reducing future frontier memorials to cold, bare numbers."}}},frontier_snow_storm:{title:"The White Disaster",desc:"A blinding December blizzard locks down the northern pass. Huo's urgent dispatch arrives at the cost of three spent horses: padded winter gear is lacking, over a hundred men have frozen to death, and mutiny brews in the drifts.",choices:{drain_vault:{text:"Grit your teeth, squeeze 300,000 taels from the vault, and rush winter supplies north",outcome:"Supply wagons brave the howling gale. A fortnight later, a blood-inked scroll arrives from the gate, stamped with the thumbprints of every commander. The frontier holds, but your coffers are bare."},ignore_storm:{text:"Command them to hold their posts at all costs; the court has nothing to spare",outcome:"The snow buries a suppressed uprising along with the frostbitten dead. A gaping tear forms in the northwestern defense line, and everyone knows what follows."}}},frontier_deserter:{title:"The Deserter",desc:"A soldier slipped away at the changing of the guard. They caught him three li north. Military law says beheading. Huo has him on his knees in front of you. Your call, Majesty.",choices:{behead:{text:"Behead him, as the law says",outcome:"It was done below the gate, and the whole city came to watch. The blood soaked into the snow and the new snow covered it by evening. Nobody ran that night."},spare:{text:"Spare him. Send him to the farms",outcome:"You pardoned him and sent him to the Hexi garrison farms. Huo's hands shook when he took the edict — not from anger. One fewer man on the wall."},hand_back:{text:"Hand him back to Huo",outcome:"You said army matters belong to the army. Huo bowed and rose. Three days later a report came: the deserter had been executed. He never said whose hand did it."}}},frontier_wall_crack:{title:"The Crack",desc:"The third stretch of wall has split — from the battlement all the way down to the footing. Wind pours through it. At night you can hear the wall creak. The works ministry says it was built thirty years ago with salvaged brick. Thirty thousand taels to fix.",choices:{repair:{text:"Send the silver",outcome:"Thirty thousand taels, and the labourers went up. On the seventh day the crack closed. The new brick is a different colour from the old, and it shows."},patch:{text:"Prop it with timber for now",outcome:"The timber held, and it looked repaired. Huo stood at the foot of the wall and looked up for a long time. Then he said: wood rots, Majesty."},ignore:{text:"Leave it",outcome:"You buried the memorial in the pile. The wind kept coming through. At night the wall still creaked — one knock after another, like someone inside it."}}},frontier_name_wall:{title:"The Names",desc:"Inside the gate there is a brick wall carved with the names of the dead. The last line is unfinished — the man who was carving it died before he got to the end. Huo holds out a chisel.",choices:{add_name:{text:"Carve it yourself",outcome:"You crouched at the wall for half an hour until your fingers split. When you straightened up, Huo was standing behind you. He said nothing. He took the chisel."},order_monument:{text:"Order a stone stele instead",outcome:"The stele went up, cut in formal court script, very neat. Huo took his men to see it and came back with one remark: it looks better than brick."},walk_away:{text:"Turn and walk away",outcome:"You brushed the dust off your hands and left. Nobody called after you. Back in the hall there was still brick dust under your nails."}}},frontier_beacon:{title:"The Beacon",desc:"At the third watch the westernmost tower lit its fire. The next one lit. The third did not. The watchman kneels below you and asks: do we light it?",choices:{light:{text:"Light it",outcome:"The whole line burned until dawn. At first light the scouts came back: herders burning grass. The camps broke and re-formed three times that night."},wait:{text:"Wait one more quarter",outcome:"You waited. The third tower never lit. You did not light yours. By dawn word came from the west: three villages were gone."},scout:{text:"Send scouts first",outcome:"They were gone two hours and came back on a ruined horse. Empty ground, they said. Nothing but burnt grass. The beacon was never lit, and you never slept."}}},frontier_salt_cart:{title:"Under the Salt",desc:"Huo's men brought in a convoy of salt carts, seized contraband. Lift the matting and there are thirty thousand catties of iron underneath. Good iron. From the north.",choices:{take_iron:{text:"Take it. Stop asking",outcome:"The iron went into the store and the ledger says SEIZED. You never asked where it came from. Seven thousand arrowheads came out of that iron."},pay_fair:{text:"Pay market price, and find out where it came from",outcome:"You had the treasury pay full price, then asked three times where it came from. The carters answered without a single gap. Good iron, clean ledger."},seize_cart:{text:"Take the carts, let the men go",outcome:"The salt went to the state. The men were driven out of the gate. Three days later Huo reported that the convoy had been robbed beyond the pass. None survived."}}},frontier_huo_drink:{title:"One Jar of Wine",desc:"Huo came without his armour, carrying a jar. From his home county, he said. Three years and he never finished it. Halfway through he said: I have buried three thousand men.",choices:{drink:{text:"Finish it with him",outcome:"You drank until dawn. He never mentioned the three thousand again — only kept saying, it wasn't that I wouldn't hold. When you set the bowl down the sky was grey."},ask_graves:{text:"Ask where they are buried",outcome:"Three li outside the walls, he said. No stone. You asked why no stone. He said: the report I sent up called it a rout."},send_away:{text:"Send him back to the wall",outcome:"You told him the wall could not spare him. He rose and withdrew. The jar stayed where it was. Nobody ever moved it."}}},frontier_siege:{title:"Below the Wall",desc:"Thirty thousand northern horse, three sides surrounded. Eight thousand arrows left in the city — two days of fighting. Huo stands on the battlement with snow all over his armour. He asks: hold, Majesty, or go?",choices:{hold_wall:{text:"Hold",outcome:"Six days. On the seventh morning they withdrew. There was no time to bury the men who froze on the wall, so they laid them at its foot. He made sure you never saw them."},use_repaired_wall:{text:"Hold where the wall was repaired",outcome:"The rebuilt stretch took the first ramming without giving. Huo shouted from the battlement: Majesty, this wall is sound! You had never heard him shout so loud.",req:"You never had that stretch repaired"},stand_with_huo:{text:"Go up. Stand with Huo",outcome:"You went up onto the wall. The soldiers froze when they saw you, and then one of them shouted. After that shout the wall was never breached.",req:"You never shared that jar with him"},abandon_wall:{text:"Give up the wall. Fall back to the inner city",outcome:"You gave the order. Huo knelt at the gate and did not stop you. On the road to the inner city you could still hear the fighting behind you."},ride_out:{text:"Open one gate. Ride out alone and meet him.",win:"The gate opens a hand's width. You ride out alone and stand before the lines for half an hour. He withdraws, on condition that half the market tax next year is his. When you come back the men on the wall do not cheer. They are looking at the snow on your shoulders.",lose:"You ride out and do not come back. He keeps you in his tent three days, makes you watch his men build ladders. On the fourth he lets you go, and the flag on the wall has already changed. They say you signed the surrender yourself. You do not deny it."}}},frontier_siege_broken:{title:"The Wall Gave Way",desc:"The crack opened on the third ramming. They came through it — the wall was shorter than a man there. Huo and what was left of his men are plugging the gap. He turns and shouts at you: go!",choices:{plug_gap:{text:"Open the treasury, pay for labour, close the gap",outcome:"The silver went out on the spot and every man in the city went up. Four hours to close it. They carried down more than a hundred."},street_fight:{text:"Don't plug it. Fall back and fight in the streets",outcome:"It came down to the alleys. Three days later they withdrew, and half the city had burned. You walked the streets and nobody looked up."},abandon_wall:{text:"Give up the wall. Fall back to the inner city",outcome:"You gave the order. Huo did not kneel and did not speak. He drove his sword into the ground at the gate and fell back with the rest."}}},frontier_watch_night:{title:"Night Watch",desc:"You sat on the gatehouse all night. The charcoal in the brazier burned down to white. The watch stamped their feet against the cold and said nothing.",choices:{walk_wall:{text:"Walk the whole wall",outcome:"You walked the full circuit. By the time you came back your fingers could not close. The watch saw you and stood a little straighter."},sit_fire:{text:"Sit by the brazier",outcome:"You sat by the fire until dawn, listening to them talk quietly about home. None of them knew who you were."}}},vault_empty:{title:"The books",desc:"The revenue board reports: one hundred and ten thousand taels. Next month requires four hundred and seventy thousand — three border armies, the capital salaries, the river works. The old clerk pushes the abacus away and says: sire, I cannot make it add up.",choices:{levy:{text:"Levy an extra year's tax",outcome:"The order is posted in the counties. Three months later a new column appears in the judicial memorials: tax resistance. You count five hundred thousand new taels in the treasury. They stack very neatly."},cut:{text:"Cut the court, cut the table, cut the music",outcome:"You halve the palace budget, including the Dowager's charcoal. The two hundred and fifty thousand saved doesn't cover the gap. The next day she sends over an old quilt and says nothing at all."},borrow:{text:"Borrow from the Jiangnan merchants",outcome:"Four hundred and fifty thousand, six months, thirty percent. The silver arrives and so does the ledger. When the merchant guild comes to give thanks, they ride in a sedan you granted — wider than a second-rank minister's."}}},vault_famine:{title:"The memorial from Henan",desc:"It says: severe drought, people eating people, granaries sealed. What it means is six words long: open them or don't, but now. Opening costs five hundred thousand taels. Not opening won't necessarily kill those people — but someone else will say it for you.",choices:{open_granary:{text:"Open everything",outcome:"Five hundred thousand taels leave the treasury and the first grain carts roll three days later. When the first snow comes, the refugees have not moved south. The county magistrates send a petition with fingerprints pressed all over it."},half:{text:"Open half, make the province cover the rest",outcome:"Two hundred thousand goes out and the province collects next year's tax early. Nobody eats anybody. Henan also only remits sixty percent of its revenue this year."},shut:{text:"Seal them and post troops",outcome:"The order is cold: granaries are the foundation of the army and the state, and will not be touched. When winter ends, one line remains in the memorial: Henan's population is down by a hundred and ten thousand. You read it three times, then burn it."}}},vault_merchant:{title:"A draft",desc:"The largest salt merchant in Jiangnan sends a draft for seven hundred thousand taels and no request attached. The courier says: we only ask the emperor to remember our house. The money is clean. Clean money usually has a price.",choices:{take:{text:"Take it",outcome:"The draft goes into the treasury and you sign nothing. Six months later Jiangnan has thirty extra salt licenses. The revenue board calls it precedent. Nobody answers who set it."},refuse:{text:"Return it with one sentence",outcome:"The draft goes back sealed. You send one line with it: the emperor does not lack silver, he lacks people. That house later donates thirty thousand piculs of grain, unsigned."}}},vault_eunuch_cut:{title:"The house rule",desc:"Everything entering and leaving the inner treasury passes through the Directorate's hands, and one part in a hundred sticks to them. It has stuck for decades and the ledger calls it 'tea money'. The chief eunuch kneels with the book held above his head.",choices:{audit:{text:"Audit it, root and branch",outcome:"Thirty-seven thousand taels found, thirty recovered, the rest 'given to the servants'. The Directorate gets a new chief who can't read the old handwriting, and so the old rule dies of illiteracy."},share:{text:"Leave the rule, but make him owe you",outcome:"You don't touch the rule. You only require a copy of the ledger on your desk. Three months later he sends thirty thousand taels unprompted and calls it 'court surplus'."}}},frontier_tribute:{title:"The northern envoy",desc:"The envoy presents his state letter: a hundred thousand bolts of silk, thirty thousand catties of iron, in exchange for the phrase 'brothers forever'. Your father paid this once. Huo Lie's dispatch arrives the same hour: fewer than thirty thousand arrows in the city.",choices:{pay:{text:"Pay it, buy three years",outcome:"Silk and iron go north. The envoy gets drunk at the banquet and says something true: your emperor is easier to talk to than his father. Someone repeats it to you, word for word."},war:{text:"Refuse. Ask whether his master's blade is still sharp",outcome:"The north wind rises the day the envoy leaves. Twenty days later the gate is under attack. You climb the wall once to see it yourself. Blood freezes black in the brick joints. You win that battle and lose a piece of your lung."},stall:{text:"Stall. Say it will be discussed",outcome:"The envoy stays in the guest house two months and leaves with an ambiguous answer. There is no war and no peace. It is the cheapest arrangement and the most exhausting."}}},frontier_general_ask:{title:"He wants grain",desc:"Huo Lie comes himself, no armour. He says there are thirty-seven thousand men at the north gate waiting for this month's grain, and the court has sent rations for twenty thousand. Then he kneels. The first time.",choices:{grant:{text:"Cover the shortfall from the treasury",outcome:"Three hundred and fifty thousand taels, taken from the tomb works. Huo Lie pauses on the palace steps and looks back: sire, the north will remember these three hundred and fifty."},deny:{text:"Pay the old quota, tell him to cut the army",outcome:"You have done the arithmetic: cut ten thousand men, the saving is exactly enough. He doesn't argue. He says one word: yes. Back north, he cuts the veterans and keeps the ones who can fight."}}},frontier_defect:{title:"The letters",desc:"What the agents brought back is spread across the desk: three letters in Huo Lie's hand, with the northern seal. Dated last winter — the three months he went unpaid. Not one word about surrender. They discuss the price of grain and the price of horses.",choices:{execute:{text:"Charge him with treason, bring him in chains",outcome:"The imperial commissioner arrives while Huo Lie is on the drill ground. He doesn't resist; he tells his second to put his armour away properly. In the capital he offers no defence, only four words on the confession: I sold horses, not the country. You sign."},pardon:{text:"Burn the letters and promote him",outcome:"You drop all three into the brazier one at a time, and he watches every one of them go. You make him General of the North and add three thousand households to his fief. His eyes are red when he leaves. You can't tell whether that's the fire."}}},chamber_dowager:{title:"A word with the Dowager",desc:"She has the lamps taken away except one. She says: your father wanted to rule at twenty-nine too. The next year he was ill. Then she says: it isn't that I won't let you sit in that chair. I don't want to watch you fall off it.",choices:{obey:{text:"Ask her to keep the curtain",outcome:"She nods and puts her hand over yours. It is very cold. The next day the curtain is exactly where it was. The Chancellor's eyes relax when he looks at you, the way they'd relax on an old object with no deadline."},refuse:{text:"I will carry it myself",outcome:"She looks at you for a long time, then smiles. It is not a warm smile. She says: very well. From that day she never asks about state affairs again, and never sends soup again either."},ask_truth:{text:"Ask how my father died",outcome:"The wick pops. She takes her hand back and says: you finally asked. Then she talks for half an hour, and when she finishes she blows out the lamp. In the dark she says: now you know too. You won't sleep from tonight."}}},chamber_insomnia:{title:"Not sleeping",desc:"It's the third watch and your eyes are open. The guard changes outside; the footsteps are quiet. You could lie here until dawn. You could also get up and look at something.",choices:{sleep:{text:"Think nothing. Sleep",outcome:"You dream about the woods on the autumn hunt. When you wake, it has been light for three hours. It is the deepest sleep you've had this month."},memorials:{text:"Get up and go through the papers",outcome:"You find a memorial nobody submitted, tucked inside an old file. It describes a place you've never been and events you've never heard of. Your eyes ache by dawn."}}},chamber_poison:{title:"The medicine",desc:"The physician brings the calming decoction as usual. There is something in it that does not belong to the prescription, faint, like almond. The rim of the bowl has a fresh chip. The man who carried it is still kneeling outside the door.",choices:{purge:{text:"Take the carrier, the brewer, the taster",outcome:"Seventeen people go into the imperial prison. They give up a steward in the inner court, and the steward gives up the north. You cut the thread at the steward. Following it further would hurt."},hide:{text:"Pretend to drink it. Say nothing",outcome:"You pour it into a planter. The orchid is dead by morning. You start memorising the face of whoever brings the bowl, and you start keeping a silver needle in your sleeve."},swap:{text:"Swap the bowls and make him drink it",outcome:"He drinks it with a shaking hand and kneels for an hour. Nothing happens. Perhaps you were wrong about the almond. Either way, he will not bring a second bowl."}}},study_veritable_record:{title:"The veritable record",desc:"The record office sends the late emperor's final year, brushed in regular script on yellow silk. Three places are left blank for you to decide. The first is three characters: the emperor is unwell. The chief compiler kneels below and waits to hear whether you will change it.",choices:{write_truth:{text:"Write it true: took medicine, died suddenly",outcome:"His hands shake as he receives the order. Once those characters are on the silk they can never come out again. You sit until dark and understand something: what you have written is not your father's cause of death. It is your own, and one day someone will write it the same way."},soften:{text:"Change it to 'a slight chill, much worse by morning'",outcome:"The chief compiler breathes out and writes quickly. The silk is rolled and sealed in its cabinet. This court's greatest skill is turning one thing into another thing, and doing it gracefully."},leave_blank:{text:"Leave it blank",outcome:"The three characters stay where they are, empty as a hole. The historian glances up once and does not ask. He knows the page will be filled eventually — by you, or by someone else."}}},study_physician:{title:"The imperial physician",desc:"The physician kneels outside the curtain and speaks through the gauze: Your Majesty is not ill, Your Majesty is being spent. He offers three prescriptions — calming, strengthening, and one circled in vermilion with two characters beside it: not advisable.",choices:{take_calming:{text:"Take the calming draft. Sleep three watches.",outcome:"It is bitter and leaves your throat numb. You sleep until the morning watch and wake to full daylight with the memorials exactly as they were. For half a day you owe nothing to anyone except a whole morning of your own."},refuse_drugs:{text:"Refuse. Put the prescription under the inkstone.",outcome:"You go on reviewing until the third watch, until the brush shakes, and then you switch hands. At morning court you stand very steady and no one notices. The physician kneels on the steps and says nothing at all."},ask_father_drug:{text:"Ask him who prescribed the late emperor's last dose",req:"Requires knowing the truth, or having questioned the lecturer",outcome:"The breathing beyond the curtain stops for a moment. He says: this subject was only an assistant then. The prescription came from the college. The medicine was — he stops there and does not go on. You finish it for him: was sent in from the inner court. He does not deny it."}}},study_banned_book:{title:"A book that should not be in the palace",desc:"A book has appeared on your desk. Cheap paper, woodblock print, the corners worn soft from reading: Twelve Discourses on Order and Disorder. The first line reads: the empire's sickness is not at the frontier. It is in the palace. The book was banned in your father's reign.",choices:{read_it:{text:"Read it end to end",outcome:"By the seventh discourse it is daylight. Every point it makes, you have seen walking around this court in a robe. You close it feeling you have not read a book but a verdict, written long ago and waiting."},trace_it:{text:"Hand it to the secret police. Find the printer.",outcome:"Three days. A failed examination candidate, two rooms in the south of the city, cutting his own blocks and pulling his own sheets. Seven hundred copies are confiscated and burned in the yard half the night. You watch from the corridor and feel something burning with them."},burn_it:{text:"Into the bronze brazier",outcome:"The paper is poor and goes fast, with a smell of oil smoke. You watch it finish, level the ash, and go back to the memorials. A banned book should not have a second copy in the palace."}}},study_omen:{title:"Mars in the heart",desc:"The astronomer kneels at the steps with a shaking voice: Mars has taken station in the Heart, an omen of a change of rule. On the chart he holds up, the red star sits in the Heart lodge and has not moved for three nights.",choices:{edict_of_blame:{text:"Issue an edict of self-blame",outcome:"You write it yourself, revise four times, and keep three hundred characters. When you read it to the astronomer he weeps and knocks his head on the floor. You know an edict cannot stop a planet, but it can make three hundred thousand people feel that someone in this court will still admit a fault."},rebuke_astrologer:{text:"Call it nonsense. Send him out of the observatory.",outcome:"He is demoted to an idle post in the southern capital. He leaves the chart at the bottom of the steps. On it, beside the Heart lodge, there is a line in his small hand: this subject dare not deceive heaven, and dare not deceive the emperor."},rewrite_stars:{text:"Order him to redraw the chart and report again",outcome:"The chart presented the next day has Mars one inch to the side. It passes, and from then on every star chart must be reviewed by the inner court before it is filed. You keep the people's faith and lose something harder to get back."}}},study_tutor_resign:{title:"The lecturer asks leave",desc:"The lecturer is old. He finishes the last passage, sets the book on the desk with both hands pressed flat, and says: this subject can no longer lecture. The book is better with Your Majesty than with me.",choices:{keep_him:{text:"Keep him. Make him a grand guardian.",outcome:"He stumbles on the thanks and catches the pillar. After that he comes every third day, lecturing shorter and shorter, sometimes reading one passage and then simply sitting. You know he is not teaching any more. He is keeping you company until court disperses."},let_him_go:{text:"Let him go home. Three thousand taels.",outcome:"He leaves without ceremony: one cart, two cases. You watch from the wall as the cart goes out the west gate. The book he left is a copy; the original stays on your desk, and on its flyleaf a line in his hand: may Your Majesty finish it."},take_book_only:{text:"Take the book. Keep no one.",outcome:"He withdraws with a very old-fashioned bow, knees bending deep. The book is volume nine of the Comprehensive Mirror, the most worn of the set, beginning with the fall of the Han."}}},study_banned_author:{title:"The man who wrote it",desc:"The prefecture reports: the author has been caught. A failed candidate, thirty-seven, still writing in his cell. The jailer says he made one request — this body, for one reading by the emperor.",choices:{release_and_meet:{text:"Release him. Grant an audience.",outcome:"He kneels in the hall still smelling of the cell. You ask: do you hate this court. He says: this subject hated that no one read it. You keep him for a meal and send him to the college with a post and no rank. He writes thirteen more books. None of them is ever banned."},exile_him:{text:"Exile him three thousand li",outcome:"The order reads: reckless speech about state affairs. No one sees him off. Three years later a dispatch from the north says an exile is teaching the soldiers' children to read, seventy of them, and requests commendation. You know the name."},leave_in_jail:{text:"Leave him there. Ask nothing.",outcome:"The case sits at the Ministry of Justice for half a year. He finishes the book in his cell and has a second one smuggled out; you do not read it. Some men's words reach you only at the moment you are least able to hear them."}}},study_petition_stone:{title:"The stone at the village gate",desc:"Shandong sends a rubbing. The villagers carved your edict of self-blame into the stone at their gate; the characters were written by the village schoolmaster and two are cut crooked. The magistrate attaches one line and asks for instruction: should the stone be destroyed.",choices:{let_it_stand:{text:"Let it stand",outcome:"Two characters in vermilion: not necessary. The rubbing hangs on the west wall of the study, on rough paper, the two crooked characters visible at a glance. You rarely look at it. But whenever someone says the people's heart is usable, your eyes go that way."},destroy_it:{text:"Destroy it. Ban private carving of edicts.",outcome:"The stone is broken and the pieces used to mend the village road. The magistrate is thorough and sends a letter of thanks. The next year Shandong's grain tax comes in remarkably smoothly. So smoothly that it makes you cold."},copy_it:{text:"Take a copy. Send one back.",outcome:"You have two rubbings made: one kept, one returned to Shandong with a note — the stone need not be destroyed; the characters may be recut. Three months later a new rubbing arrives. The two crooked characters are straight and the carving is by the county school's instructor."}}},study_lecture:{title:"The lecture",desc:"The lecturer is reading the Book of Documents. At 'Heaven has no favourites; it aids only the virtuous' he pauses, glances up at you, then reads on. There are three people in the hall: him, you, and the historian recording everything in the corner.",choices:{listen:{text:"Hear him out, then ask what virtue is",outcome:"He answers slowly: virtue is getting — getting it in the heart, not borrowing it from men. You understand half. The other half will take years: that not borrowing it from men means no one can be emperor in your place."},ask_father:{text:"Ask whether the late emperor heard this too",outcome:"His scroll stops in the air. A long while later he says: when the late emperor heard this passage, this subject did not dare look up. The lecture ends early. You sit alone in the hall until the sun goes down."},cancel:{text:"Cancel today",outcome:"The lecturer withdraws with the book, very correct. You have saved an hour, to sleep or to stare at nothing. The lecture is the only place in this court still teaching you anything, and you have closed it."}}},study_river_works:{title:"The river viceroy's memorial",desc:"One page: the autumn flood is coming, seven sections of the dike are weak, three hundred thousand taels are needed. Attached is a map, seven circles in vermilion, each with the name of a village written beside it.",choices:{fund:{text:"Release three hundred thousand taels. Repair all seven.",outcome:"The silver leaves the capital in three shipments. Autumn passes and not one of the seven breaches. The viceroy's reply says: the dike stands; the elders along the river wish to present the umbrella of ten thousand names. You read it twice before remembering you have never seen that river."},partial:{text:"Repair only the two nearest the capital",outcome:"You circle the two closest to the capital. The viceroy does not mention the other five again. At the end of the memorial he writes one small line: this subject will do what he can."},refuse_works:{text:"The treasury is empty. Defer it.",outcome:"Defer — two characters in vermilion, written lightly. No further memorial comes. You roll up the map and put it on the second shelf. All autumn you wait for news from the northern gate, and none from the river."}}},study_land_ledger:{title:"Three hundred and twenty-seven ledgers",desc:"The survey ledgers are carried into the study, three hundred and twenty-seven of them, stacked to a man's chest. You pull one from the middle at random: eleven pages have been torn out at the root, and the tear is fresh. A scrap of paper in the gutter holds one character: Shen.",choices:{audit:{text:"Collect on the books. Not one name spared.",outcome:"The recovered silver fills an entire room of the inner treasury. Three great houses are confiscated, one of them bearing a plaque the late emperor wrote himself. The Chancellor stands outside a long time before entering, and then says only: after this, no one will dare hide anything."},burn_ledger:{text:"Burn the ledgers too",outcome:"You burn them in the bronze brazier all night. Two jars of ash go into the palace canal. The next day the south sends a letter of thanks listing twenty-seven names, every one of them willing to 'contribute salary to the army'."},keep_ledger:{text:"Lock them away. Show no one.",outcome:"The ledgers go into the deepest shelf of the inner vault. You neither collect nor burn. Three hundred and twenty-seven books that say nothing, and remind you every day that you hold a blade you have not brought down."}}},study_intercepted_letter:{title:"The intercepted letter",desc:"The agents bring it in with the wax still intact. It is addressed to the commander of the capital guard — the Dowager's brother. There is no signature, but you know the hand: the old maid who has served the Dowager for thirty years. One line: after the ninth month, do not enter the palace again.",choices:{intercept:{text:"Open it, copy it, keep the original",outcome:"You copy it into a box. The original stays with the agents, unsent. Three days later the Dowager sends to ask: where is the letter. You say: lost on the road. She looks at you a long time and says: the emperor has grown up."},pretend:{text:"Reseal it. See nothing.",outcome:"You reseal it and let the agents deliver it. The wax repair is clumsy; anyone receiving it will know it was opened. From then on no rotation order from the capital guard reaches the Ministry of War on time again."},return_it:{text:"Carry it back to her yourself",outcome:"You set it on the low table in front of her and say nothing. Her hand closes inside her sleeve for a long time. At last she says: this old woman was only afraid. You ask: of what. She does not answer. The lamps in that hall burn until the fourth watch."}}},vault_private_mint:{title:"Coins a hair too thin",desc:"The vault clerk sets two strings of cash side by side: one struck by the Ministry of Revenue, one taken off the market. The market string is a hair thinner — a thousand coins weighing three taels short. The copper to make them was scraped off grain barges.",choices:{crack_down:{text:"Seal the furnaces. Trace the copper. Confiscate.",outcome:"Seven furnaces are sealed in the capital; the false coin takes three days to melt. The copper trail leads to the grain commissioner's books, and his clerk hangs himself in the storehouse that night. Overnight the coins in the market grow thick again, and the price of rice does not fall."},tax_it:{text:"Don't seal them. Take three tenths.",outcome:"Your men set a customs post outside the city that collects no tax, only a share. The counterfeiters pay on time and the coins get thinner every year. Three years later the Ministry of Revenue works it out for you: half the copper cash in the empire was not struck by the state."},ignore_mint:{text:"Pretend you didn't see it",outcome:"You keep both strings and ask nothing more. It is not a great matter. Every counterfeiter in the city can trace three generations of service to the throne."},stake_it_out:{text:"Don't seal the furnace. Wait three days and see who comes for the money.",win:"On the third night the man who comes for the money is a ministry secretary in a fourth-rank chair. Following him leads to three senior officials. The coin goes to the treasury and not one man is touched — the list on your desk is worth more than the money.",lose:"On the third night the furnace, the men and the moulds are gone. The vault is locked and the key is in your hand. Only at the end of the count do you find what is missing: not copper, but thirty thousand strings of coin already cast."}}},vault_armory:{title:"The armory",desc:"The register lists thirty thousand suits of armour and twelve thousand bows. You open the store yourself: fourteen thousand suits. The rest are stacked in the corner and look like armour, but lift like nothing — the rivets are all new. The old keeper kneels and says: these books are a dozen years old.",choices:{replenish:{text:"Fund the shortfall. Let the past go.",outcome:"Two hundred and eighty thousand taels go out; the Ministry of Works forges day and night. At the eight thousandth suit a report comes from the north: Huo Lie was ambushed beyond the pass, lost three hundred men, armour that did not cover them. You hold the memorial down on the desk for a long time."},report_it:{text:"Punish it all the way down. Three generations.",outcome:"The bureau is replaced top to bottom and a hundred and eighty thousand taels of property recovered. The new keeper is a ninth-rank clerk whose first act is to burn the empty shells in the yard; the firelight moves on the palace wall half the night."},look_away:{text:"Note the real numbers. Don't act yet.",outcome:"You have the true count copied into your own box. The empty armour goes back in the corner, the register closes as it was. Two hundred and sixty thousand taels of difference, and what it bought is four words: not yet, not yet."}}},vault_border_market:{title:"The market beyond the pass",desc:"The market is three li outside the gate, a compound of rammed earth. On the first market day more than two hundred riders come in: hides, horses, salt, heaped on the snow. The garrison commander asks how the tax is collected. By old rule, border markets are untaxed.",choices:{tax_market:{text:"Set a post. One in thirty.",outcome:"First month: fourteen hundred taels. Second: twenty-one hundred. Not much money, but it is the first silver ever taken out of the northern wind. The commander brings the tax book himself, smiling in a way that does not quite suit a soldier."},free_trade:{text:"No tax. First get them coming.",outcome:"You waive the tax for three years. By the third, the market outside the pass is busier than the county town inside it, and the horses traded for iron pots and salt are enough to remount the northern gate. Huo Lie says: this is worth more than a battle."},close_market:{text:"Close the market. No one leaves the pass.",outcome:"The earth wall comes down and the people are driven back. That night two hundred riders circle outside for a long time. They do not attack. They only make sure the men on the wall can count them."}}},vault_river_report:{title:"The umbrella of ten thousand names",desc:"The river viceroy sends an umbrella. The canopy is pieced from over three hundred squares of coarse cloth, each with the name of a village, some written in charcoal. Seven counties along the river put it together and insisted it be carried to the capital. The ribs are willow, still damp.",choices:{accept_umbrella:{text:"Accept it. Hang it in the study.",outcome:"The umbrella hangs on the west wall of the study, and sixty thousand taels of repair silver leave the treasury. At every council after that, you look up and see three hundred squares of cloth. One reads Liujiadu, in very bad handwriting."},reward_engineers:{text:"Pay the dike workers. Send the umbrella back.",outcome:"A hundred and eighty thousand taels go to the labourers, three taels each, and three years of household tax are forgiven along the river. The umbrella goes back. The viceroy writes: the people will not take the money, only the umbrella. You read that line twice."},downplay:{text:"Into the storeroom. Don't make a fuss.",outcome:"The umbrella is logged as one item, sundries. You release eighty thousand taels, less than owed. No further memorial comes. The next flood season, three hundred farmers show up on the dike with their own hoes."}}},vault_flood_crisis:{title:"The breach",desc:"On the seventeenth of the seventh month the river breaks. Three post horses die carrying the news. Three hundred thousand refugees walk north and stop at the capital's edge, because north of that is a wall. The Ministry of Revenue says the granaries hold forty days.",choices:{open_granary:{text:"Open the granaries. All of it.",outcome:"Four hundred thousand taels of grain go out and thirty-seven gruel kitchens open around the capital. One of them gets into a song, and the song says you are a good emperor. It reaches the palace while you are working out next year's tax."},work_for_food:{text:"Food for work. Rebuild the dike.",outcome:"The refugees are formed into work gangs, two thin meals a day, repairing the same section that will break next year. You stand on the dike for half a day. The wind is strong and no one recognises you. You are ill for a week after."},seal_gates:{text:"Seal the gates. Drive them off.",outcome:"Nine gates lock, shelters go up outside, and soldiers stand beyond the shelters. Twenty days later the ground outside is quiet. The historian writes fourteen characters in the daily record, sets down his brush, and does not move for a long while."}}},vault_ledger_buyer:{title:"The man who wants the ledger",desc:"He is a salt merchant, plainly dressed, and he knocks his head three times on the floor before speaking. He says: ten thousand taels for the land ledger. His fingers tremble the whole time — from fear, or from a lifetime of counting silver. Three generations of his family are in that book.",choices:{sell_ledger:{text:"Sell it. The silver goes to the treasury.",outcome:"The silver comes in, the ledger goes out. The next day seven counties in the south report land 'returned to its original owners'. You have made ten thousand taels and sold a blade you never intended to use."},expose_them:{text:"No silver. Copy it to all six ministries.",outcome:"Thirty copies go out, one to each ministry. The merchant spends three months in prison and comes out with seven tenths of his property gone. Some call you cruel. Some say this is what an emperor is for."},keep_quiet:{text:"Take no money. Give him nothing.",outcome:"He kneels an hour and you say nothing. At last he stands up on his own and withdraws. The ledger stays where it is. He is ill for a year afterwards, and then donates three thousand mu of land to a charity school."}}}},r={ending_emperor_zenith:{title:"The Restoration",desc:"On accession day you walked out from behind the curtain and stood at the front of the hall. When Shen Yan led the hundred officials down, the words he read were not the Dowager's. The treasury could pay three years of wages, and there was no crack at the northern gate. The historian wrote: at nineteen, the emperor set the realm right. They called it a restoration."},ending_emperor_beloved:{title:"The Benevolent",desc:"You never filled the treasury. You emptied the granaries instead. On accession day the road from the palace to Zhuque Street was lined with people who had not been ordered to stand there. From the carriage you heard someone shout the salute, ragged and unrehearsed. The historian wrote: the emperor was lenient, cut taxes repeatedly, and the people built shrines to him."},ending_emperor_ironfist:{title:"The Iron Hand",desc:"You killed everyone who needed killing, and a few who did not. No one in that hall dares look at another man while you are speaking. The treasury is full, the border is quiet, and no memorial wastes a single word. The historian wrote: the emperor was resolute, killed too freely, and the state survived because of it."},ending_emperor_abdicate:{title:"The Abdication",desc:"At the accession ceremony you set the seal back on the desk. The whole hall stayed kneeling and would not rise. You walked out through them and no one stopped you. Only outside the gate did you notice the autumn wind was sweet. The historian wrote: the emperor yielded, and where he went is not known."},ending_emperor_puppet:{title:"The Puppet",desc:"Eighteen months later you are still behind the curtain. The Dowager says you are young. The Chancellor says wait. The general says he doesn't understand capital business. You have nodded so many times you can no longer tell which thoughts were yours. The realm is still here. It is simply not in your hands."},ending_dead:{title:"The Death of an Emperor",desc:"The physicians knelt in a row and none of them spoke first. The last thing you saw was the coiling dragon on the canopy, one flake of gilt missing. At the fifth watch the palace bell rang twenty-seven times. The historian wrote: the emperor died, aged nineteen, no heir."},ending_mad:{title:"The Madness",desc:"You began summoning dead men at midnight. In the third month the Dowager issued an edict: the sacred person is unwell and requires quiet. They moved you to the innermost room of the western garden. You lived there many years, and the whole time you believed you were holding court."},ending_starved:{title:"The Empty Treasury",desc:"On the sixteenth day without pay, the guard broke open the inner treasury. There was nothing inside but ledgers. You waited in the hall until dawn and no one came. The historian wrote: the army mutinied, the emperor died in the disorder, the dynasty broke."},ending_emperor_faded:{title:"The Caretaker",desc:"Eighteen months, and you did nothing great and nothing wrong. The accession ceremony went ahead as scheduled and you completed every step of it. The historian wrote: the emperor reigned eighteen months, no great faults, no great works. It is not a bad verdict. Nobody remembers it either."}},s={meta:e,ui:t,npcs:o,locations:a,events:n,endings:r};export{s as default,r as endings,n as events,a as locations,e as meta,o as npcs,t as ui};
